import{_ as t,o as a,c as n,ao as i}from"./chunks/framework.DbC_DlpH.js";const p=JSON.parse('{"title":"Example gallery","description":"","frontmatter":{},"headers":[],"relativePath":"gallery.md","filePath":"gallery.md","lastUpdated":null}'),s={name:"gallery.md"};function o(l,e,r,c,d,h){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="Example-gallery" tabindex="-1">Example gallery <a class="header-anchor" href="#Example-gallery" aria-label="Permalink to &quot;Example gallery {#Example-gallery}&quot;">​</a></h1><p>Each page below is generated from a script in <code>PureAtomistic/docs/examples/</code> by the documentation build. The scripts run no dynamics: they read the records in <code>PureAtomistic/bench/results/</code> (with the commit, the date and the settings of each run), stored by <code>PureAtomistic/bench/md_validation.jl</code> and, for the vacancy-diffusion page, by <code>PureAtomistic/bench/vacancy_analysis.jl</code>, and plot them. Each script also runs on its own, from the directory where its figures should go:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>julia --project=PureAtomistic/docs PureAtomistic/docs/examples/nve_conservation.jl</span></span></code></pre></div><p>The animations on the pages are rendered ahead of time with GLMakie by <code>PureAtomistic/docs/render_animations.jl</code> from the trajectories of the same runs, and committed in <code>PureAtomistic/docs/src/assets/</code>. The validation runs use MACE-MPA-0, one Julia thread and one BLAS thread; the vacancy-diffusion campaign runs MACE-MPA-0 in Float32 on the GPU (Metal).</p><table tabindex="0"><thead><tr><th style="text-align:left;">Page</th><th style="text-align:left;">Shows</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="./examples/nve_conservation">Energy conservation</a></td><td style="text-align:left;">total-energy drift and fluctuation of 500 Cu atoms over 2 ps at several time steps, and the largest stable one</td></tr><tr><td style="text-align:left;"><a href="./examples/thermostat_check">Canonical sampling</a></td><td style="text-align:left;">the Bussi thermostat at 1200 K: mean and variance of the kinetic temperature against the canonical distribution</td></tr><tr><td style="text-align:left;"><a href="./examples/vacancy_hop_md">A vacancy in hot Cu</a></td><td style="text-align:left;">one vacancy at 1300 K followed by the vacancy tracker, as an illustration</td></tr><tr><td style="text-align:left;"><a href="./examples/vacancy_diffusion">Vacancy diffusion in Cu</a></td><td style="text-align:left;">the vacancy-diffusion campaign at 900 to 1200 K: hop rates, Arrhenius fit of the migration energy, comparison with the NEB barrier and thermal expansion, cell-size check and diffusion coefficients</td></tr></tbody></table>',5)])])}const f=t(s,[["render",o]]);export{p as __pageData,f as default};
